ValidationRule.errorConditionFormula:
AND(
  /* Check if 30 days have passed since Event End */
  Event_End_Date__c + 30 < TODAY(),

  /* Check if status is Completed */
  ISPICKVAL(Status__c, 'Completed'),

  /* Check if financial fields are being changed */
  OR(
    ISCHANGED(Quoted_Price__c),
    ISCHANGED(Estimated_Budget__c)
  ),

  /* Allow if user has Finance Adjustment permission set */
  NOT($Permission.Finance_Adjust)
)
